PREFIX arch: <https://moosedev.dev/kg/ontology/software-architecture/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dcterms: <http://purl.org/dc/terms/>
SELECT ?iri ?title ?status ?supersededByTitle ?supersededByIri WHERE {
  ?iri a arch:ArchitecturalDecision ;
       rdfs:label ?title .
  OPTIONAL { ?iri arch:lifecycleStatus ?status . }
  OPTIONAL { ?new arch:supersedes ?iri ; rdfs:label ?supersededByTitle . BIND(?new AS ?supersededByIri) }
  FILTER(LCASE(STR(?status)) = "superseded" || BOUND(?new))
}
ORDER BY LCASE(STR(?title))

