PREFIX arch: <https://trivyn.io/ontologies/software/architecture/domain/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?old ?oldTitle ?new ?newTitle WHERE {
  { ?new arch:supersedes ?old . }
  UNION
  { ?old arch:isSupersededBy ?new . }
  ?old a <https://moosedev.dev/kg/ontology/software-architecture/ArchitecturalDecision> ; rdfs:label ?oldTitle .
  OPTIONAL { ?new rdfs:label ?newTitle . }
}
ORDER BY LCASE(STR(?oldTitle)) LCASE(STR(?newTitle))

